                        .header("X-Actor-Id", "ops").header("X-Approval-Role", "OPERATIONS")
                        .contentType(MediaType.APPLICATION_JSON).content("{\"commandKey\":\"CA2\"}"))
        );

        // 起始为 QUARANTINED：任一批准先获锁都因检验未全部 PASS 返回 422；
