        assertEquals(0, approvals, "存在 FAIL 的批次不得留下任何批准");
        assertEquals(201, results.get(0).get(30, TimeUnit.SECONDS));
        assertTrue(results.get(1).get(30, TimeUnit.SECONDS) == 409
                || results.get(1).get(30, TimeUnit.SECONDS) == 422);
